html_tpl = r'''<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Пройти тест DISC онлайн бесплатно — Типы личности за 5 минут</title>
<style>
:root{
  --blue:#002D7A; --blue-2:#0A3FA8; --accent:#6865D4; --bg:#F7FAFC;
  --text:#101828; --muted:#667085; --border:#E4E7EC; --card:#fff;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%}
body{
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
  color:var(--text);background:var(--bg);line-height:1.5;
  -webkit-font-smoothing:antialiased;
}
.no-scroll{overflow:hidden}
body.no-scroll{overflow:hidden}
.container{max-width:1120px;margin:0 auto;padding:0 20px}

/* header */
.header{background:var(--blue);color:#fff}
.header__wrap{display:flex;align-items:center;justify-content:space-between;height:72px}
.logo{display:flex;align-items:center;gap:10px;color:#fff;text-decoration:none;font-weight:700;font-size:20px;letter-spacing:.04em}
.logo svg{display:block}
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:10px;
  border:none;cursor:pointer;font:inherit;font-weight:600;border-radius:12px;
  padding:12px 22px;transition:transform .15s,box-shadow .15s,background .15s;
}
.btn-accent{background:var(--accent);color:#fff}
.btn-accent:hover{background:#5a57c7;box-shadow:0 8px 24px rgba(104,101,212,.35)}
.btn-accent:active{transform:translateY(1px)}

/* hero */
.hero{padding:72px 0 56px;text-align:center}
.hero__badge{
  display:inline-flex;align-items:center;gap:8px;background:#EEF2FF;color:var(--blue);
  border-radius:999px;padding:6px 14px;font-size:14px;font-weight:600;margin-bottom:20px;
}
.hero h1{font-size:clamp(28px,4.5vw,44px);line-height:1.15;max-width:760px;margin:0 auto 16px}
.hero__sub{color:var(--muted);font-size:18px;max-width:620px;margin:0 auto 32px}
.hero__hint{margin-top:18px;color:var(--muted);font-size:14px}
.disc-types{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px;max-width:880px;margin:48px auto 0;text-align:left}
.disc-type{background:var(--card);border:1px solid var(--border);border-radius:16px;padding:18px}
.disc-type b{display:flex;align-items:center;gap:10px;font-size:17px;margin-bottom:6px}
.disc-type span{color:var(--muted);font-size:14px}
.chip{width:32px;height:32px;border-radius:10px;display:inline-flex;align-items:center;justify-content:center;color:#fff;font-weight:700;font-size:15px;flex:none}
.chip-d{background:#E5484D}.chip-i{background:#F5A524}.chip-s{background:#30A46C}.chip-c{background:#0A5BD3}

/* modal */
.disc-modal{position:fixed;inset:0;z-index:50;display:none}
.disc-modal.is-open{display:block}
.disc-modal__overlay{position:absolute;inset:0;background:rgba(16,24,40,.6)}
.disc-modal__dialog{
  position:relative;z-index:1;background:var(--card);width:min(980px,calc(100% - 24px));
  max-height:calc(100dvh - 32px);margin:16px auto;border-radius:20px;display:flex;flex-direction:column;
  box-shadow:0 24px 64px rgba(16,24,40,.3);overflow:hidden;
}
.disc-modal__close{
  position:absolute;top:14px;right:14px;width:40px;height:40px;border:none;border-radius:12px;
  background:#F2F4F7;color:var(--text);font-size:22px;cursor:pointer;z-index:2;
}
.disc-modal__close:hover{background:#E4E7EC}
.disc-modal__head{padding:24px 28px 8px}
.disc-modal__title{font-size:24px}
.disc-modal__sub{color:var(--muted);font-size:14px;margin-top:4px}
.disc-modal__lead{font-size:15px;font-weight:600;margin-top:12px;color:var(--blue)}
.disc-modal__tabs{
  display:flex;gap:8px;padding:16px 28px 0;overflow-x:auto;scrollbar-width:none;
}
.disc-modal__tabs::-webkit-scrollbar{display:none}
.disc-tab{
  flex:none;border:1px solid var(--border);background:#fff;color:var(--muted);
  border-radius:999px;padding:8px 16px;font:inherit;font-size:14px;font-weight:600;cursor:pointer;
}
.disc-tab.is-active{background:var(--blue);border-color:var(--blue);color:#fff}
.disc-modal__body{padding:20px 28px 24px;overflow-y:auto}
.disc-pane{display:none}
.disc-pane.is-active{display:block}
.disc-grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
@media(max-width:860px){.disc-grid3{grid-template-columns:1fr}}
.disc-card{background:#FBFCFE;border:1px solid var(--border);border-radius:16px;padding:14px;display:flex;flex-direction:column}
.disc-card__title{font-weight:700;font-size:15px;margin-bottom:10px}
.disc-card__foot{color:var(--muted);font-size:13px;margin-top:10px;border-top:1px dashed var(--border);padding-top:10px}
.disc-list{list-style:none;display:flex;flex-direction:column;gap:8px;min-height:190px}
.disc-item{
  display:flex;align-items:center;gap:10px;background:#fff;border:1px solid var(--border);
  border-radius:12px;padding:10px 12px;font-size:14px;cursor:grab;user-select:none;touch-action:manipulation;
}
.disc-item.is-dragging{opacity:.85;box-shadow:0 8px 20px rgba(16,24,40,.18);cursor:grabbing}
.disc-item.is-over{border-color:var(--accent);border-style:dashed}
.disc-handle{flex:none;margin-left:auto;display:flex;color:#B3B3B3}
.disc-progress{height:6px;background:#EEF2F7;border-radius:999px;margin-top:22px;overflow:hidden}
.disc-progress__bar{height:100%;width:0;background:linear-gradient(90deg,var(--blue),var(--accent));border-radius:999px;transition:width .25s}
.disc-actions{display:flex;justify-content:space-between;gap:12px;margin-top:18px}
.disc-btn{border:none;border-radius:12px;padding:12px 26px;font:inherit;font-weight:600;cursor:pointer}
.disc-btn--ghost{background:#F2F4F7;color:var(--text)}
.disc-btn--ghost:disabled{opacity:.4;cursor:default}
.disc-btn--primary{background:var(--blue);color:#fff}
.disc-btn--primary:hover{background:var(--blue-2)}
.disc-btn[hidden]{display:none}

/* result */
.result{display:none;text-align:center;padding:8px 8px 8px}
.result.is-open{display:block}
.result__title{font-size:26px;margin-bottom:8px}
.result__sub{color:var(--muted);font-size:15px;margin-bottom:24px}
.result__bars{max-width:560px;margin:0 auto;text-align:left;display:flex;flex-direction:column;gap:14px}
.rbar__head{display:flex;justify-content:space-between;font-size:14px;font-weight:600;margin-bottom:6px}
.rbar__track{height:10px;background:#EEF2F7;border-radius:999px;overflow:hidden}
.rbar__fill{height:100%;border-radius:999px;transition:width .6s}
.result__dom{margin:24px auto 0;max-width:560px;background:#EEF2FF;border-radius:14px;padding:16px 18px;font-size:14px;color:var(--blue);text-align:left}
@media(max-width:640px){
  .disc-modal__head{padding:20px 18px 8px}
  .disc-modal__tabs{padding:12px 18px 0}
  .disc-modal__body{padding:16px 18px 20px}
}
