<script>
__DATA__

(() => {
  const qs = (s, r = document) => r.querySelector(s);
  const qsa = (s, r = document) => Array.from(r.querySelectorAll(s));
  const STEP_TITLES = ["Первый","Второй","Третий","Четвертый","Пятый","Шестой","Седьмой","Восьмой"];
  const TYPE_INFO = {
    d:{name:"Доминирование (D)", color:"#E5484D", desc:"Ориентация на результат, решительность, волю к лидерству."},
    i:{name:"Влияние (I)",       color:"#F5A524", desc:"Эмоциональность, убедительность, контактность."},
    s:{name:"Постоянство (S)",   color:"#30A46C", desc:"Спокойствие, терпение, надёжность и преданность."},
    c:{name:"Соответствие (C)",  color:"#0A5BD3", desc:"Точность, осмотрительность, внимание к качеству."}
  };

  const wizard = qs("#wizardmodal");
  const tabsEl = qs("#tabs");
  const panesEl = qs("#panes");
  const bodyEl = qs("#rootwizard");
  const leadText = qs("#leadText");
  const progressEl = qs("#discProgress");
  const btnPrev = qs("#btnPrev");
  const btnNext = qs("#btnNext");
  const btnFinish = qs("#btnFinish");
  const actionsEl = qs("#actions");

  let step = 0;
  let lastFocus = null;

  // ---------- build tabs & panes ----------
  QUESTIONS.forEach((_, idx) => {
    const t = document.createElement("button");
    t.className = "disc-tab" + (idx === 0 ? " is-active" : "");
    t.type = "button"; t.setAttribute("role","tab");
    t.setAttribute("aria-selected", idx === 0 ? "true" : "false");
    t.dataset.stepBtn = idx;
    t.textContent = STEP_TITLES[idx];
    t.addEventListener("click", () => { setStep(idx); });
    tabsEl.appendChild(t);

    const pane = document.createElement("div");
    pane.className = "disc-pane" + (idx === 0 ? " is-active" : "");
    pane.dataset.stepPane = idx;
    pane.setAttribute("role","tabpanel");

    const grid = document.createElement("div");
    grid.className = "disc-grid3";

    QUESTIONS[idx].forEach((card) => {
      const c = document.createElement("div");
      c.className = "disc-card";
      const title = document.createElement("div");
      title.className = "disc-card__title";
      title.textContent = "Я наиболее";
      const ul = document.createElement("ul");
      ul.className = "disc-list";
      card.forEach((it) => {
        const li = document.createElement("li");
        li.className = "disc-item";
        li.dataset.type = it.t;
        li.innerHTML = '<span class="lbl"></span>';
        li.querySelector(".lbl").textContent = it.w;
        li.appendChild(makeHandle());
        ul.appendChild(li);
      });
      const foot = document.createElement("div");
      foot.className = "disc-card__foot";
      foot.textContent = "Я наименее";
      c.append(title, ul, foot);
      grid.appendChild(c);
    });

    pane.appendChild(grid);
    panesEl.appendChild(pane);
  });

  function makeHandle(){
    const h = document.createElement("span");
    h.className = "disc-handle";
    h.setAttribute("aria-hidden","true");
    h.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16" fill="currentColor"><circle cx="4" cy="2.5" r="1.2"/><circle cx="10" cy="2.5" r="1.2"/><circle cx="4" cy="8" r="1.2"/><circle cx="10" cy="8" r="1.2"/><circle cx="4" cy="13.5" r="1.2"/><circle cx="10" cy="13.5" r="1.2"/></svg>';
    return h;
  }

  // ---------- modal ----------
  const openWizard = () => {
    lastFocus = document.activeElement;
    wizard.classList.add("is-open");
    wizard.setAttribute("aria-hidden","false");
    document.documentElement.classList.add("no-scroll");
    document.body.classList.add("no-scroll");
    qs(".disc-modal__close", wizard).focus({preventScroll:true});
  };
  const closeWizard = () => {
    wizard.classList.remove("is-open");
    wizard.setAttribute("aria-hidden","true");
    document.documentElement.classList.remove("no-scroll");
    document.body.classList.remove("no-scroll");
    if (lastFocus && lastFocus.focus) lastFocus.focus({preventScroll:true});
  };

  qsa("[data-disc-close]", wizard).forEach(x => x.addEventListener("click", closeWizard));
  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    if (wizard.classList.contains("is-open")) closeWizard();
  });

  // ---------- drag & drop (pointer-based, works on desktop + touch) ----------
  function makeSortable(ul){
    let dragEl = null;
    let startY = 0, startX = 0;

    ul.addEventListener("pointerdown", (e) => {
      const li = e.target.closest(".disc-item");
      if (!li || !ul.contains(li)) return;
      // пропускаем клики (без движения) — сортировка по факту перемещения
      dragEl = li;
      startX = e.clientX; startY = e.clientY;
      li.setPointerCapture && li.setPointerCapture(e.pointerId);
    });

    ul.addEventListener("pointermove", (e) => {
      if (!dragEl) return;
      if (Math.abs(e.clientY - startY) < 4 && Math.abs(e.clientX - startX) < 4) return;
      if (!dragEl.classList.contains("is-dragging")) dragEl.classList.add("is-dragging");
      const overLi = document.elementFromPoint(e.clientX, e.clientY);
      const target = overLi && overLi.closest ? overLi.closest(".disc-item") : null;
      if (!target || !ul.contains(target) || target === dragEl) return;
      const rect = target.getBoundingClientRect();
      const before = (e.clientY - rect.top) < rect.height / 2;
      ul.insertBefore(dragEl, before ? target : target.nextSibling);
    });

    const end = () => {
      if (!dragEl) return;
      dragEl.classList.remove("is-dragging");
      dragEl = null;
    };
    ul.addEventListener("pointerup", end);
    ul.addEventListener("pointercancel", end);
    // фолбэк: HTML5 DnD (если pointer events по какой-то причине не сработали)
    qsa("li", ul).forEach(li => {
      li.setAttribute("draggable","true");
      li.addEventListener("dragstart", (e) => { dragEl = li; li.classList.add("is-dragging"); e.dataTransfer.effectAllowed = "move"; });
      li.addEventListener("dragend", () => { li.classList.remove("is-dragging"); dragEl = null; });
      li.addEventListener("dragover", (e) => {
        e.preventDefault();
        if (!dragEl || dragEl === li) return;
        const rect = li.getBoundingClientRect();
        const before = (e.clientY - rect.top) < rect.height / 2;
        ul.insertBefore(dragEl, before ? li : li.nextSibling);
      });
    });
  }
  qsa(".disc-list", wizard).forEach(makeSortable);

  // ---------- steps ----------
  const tabs = qsa("[data-step-btn]", wizard);
  const panes = qsa("[data-step-pane]", wizard);

  function setStep(n){
    step = Math.max(0, Math.min(7, n));
    tabs.forEach(t => {
      const is = Number(t.dataset.stepBtn) === step;
      t.classList.toggle("is-active", is);
      t.setAttribute("aria-selected", is ? "true" : "false");
    });
    panes.forEach(p => p.classList.toggle("is-active", Number(p.dataset.stepPane) === step));
    btnPrev.disabled = step === 0;
    btnNext.hidden = step === 7;
    btnFinish.hidden = step !== 7;
    progressEl.style.width = ((step + 1) / 8 * 100) + "%";
    bodyEl.scrollTo({top:0, behavior:"smooth"});
  }

  btnPrev.addEventListener("click", () => setStep(step - 1));
  btnNext.addEventListener("click", () => setStep(step + 1));
  btnFinish.addEventListener("click", showResult);

  // ---------- score ----------
  function score(){
    const maj = [], min = [];
    qsa(".disc-list", wizard).forEach(ul => {
      const lis = qsa("li", ul);
      maj.push(lis[0].dataset.type);
      min.push(lis[3].dataset.type);
    });
    const count = (arr, ch) => arr.reduce((a,v) => a + (v === ch ? 1 : 0), 0);
    return {
      d: count(maj,"d") - count(min,"d"),
      i: count(maj,"i") - count(min,"i"),
      s: count(maj,"s") - count(min,"s"),
      c: count(maj,"c") - count(min,"c")
    };
  }

  function showResult(){
    const sc = score();
    const head = qs("#wizardHead");
    const total = Math.max(1, Math.max(...Object.values(sc).map(Math.abs)));
    head.innerHTML =
      '<h2 class="disc-modal__title">Ваши результаты</h2>' +
      '<div class="disc-modal__sub">Балл каждого типа: +1 за «Я наиболее» на первом месте и −1 за «Я наименее» на последнем.</div>';
    bodyEl.innerHTML =
      '<div class="result is-open">' +
      '<div class="result__bars">' +
      Object.keys(sc).map(k => {
        const info = TYPE_INFO[k], v = sc[k];
        const pct = Math.round(Math.abs(v) / total * 100);
        return '<div class="rbar"><div class="rbar__head"><span>' + info.name + '</span><span>' + (v > 0 ? "+" : "") + v + '</span></div>' +
          '<div class="rbar__track"><div class="rbar__fill" style="width:' + pct + '%;background:' + info.color + '"></div></div></div>';
      }).join("") +
      '</div>' +
      '<div class="result__dom" id="domText"></div>' +
      '<div class="disc-actions" style="justify-content:center"><button class="disc-btn disc-btn--primary" type="button" id="btnAgain">Пройти тест заново</button></div>' +
      '</div>';
    const keys = Object.keys(sc);
    const topKey = keys.reduce((a,b) => sc[b] > sc[a] ? b : a, "d");
    qs("#domText").innerHTML = '<b>Ведущий тип: ' + TYPE_INFO[topKey].name + '.</b> ' + TYPE_INFO[topKey].desc;
    qs("#btnAgain").addEventListener("click", () => location.reload());
    tabsEl.style.display = "none";
    actionsEl.style.display = "none";
    progressEl.parentElement.style.display = "none";
  }

  qs("#btnOpen").addEventListener("click", openWizard);
  qs("#btnOpen2").addEventListener("click", openWizard);
})();
</script>
</body>
</html>
