edits.newText:
function makeSortable(ul){
  let dragEl = null;
  let started = false;
  let sx = 0, sy = 0;

  ul.addEventListener("pointerdown", (e) => {
    if (e.button !== undefined && e.button !== 0) return;
    const li = e.target.closest(".disc-item");
    if (!li || !ul.contains(li)) return;
    dragEl = li;
    started = false;
    sx = e.clientX; sy = e.clientY;
    e.preventDefault();
  });

  document.addEventListener("pointermove", (e) => {
    if (!dragEl) return;
    if (!started) {
      if (Math.abs(e.clientY - sy) < 4 && Math.abs(e.clientX - sx) < 4) return;
      started = true;
      dragEl.classList.add("is-dragging");
    }
    const el = document.elementFromPoint(e.clientX, e.clientY);
    const target = el && el.closest ? el.closest(".disc-item") : null;
    if (!target || !ul.contains(target) || target === dragEl) return;
    const rect = target.getBoundingClientRect();
    const before = (e.clientY - rect.top) < rect.height / 2;
    ul.insertBefore(dragEl, before ? target : target.nextSibling);
  }, {passive:true});

  const end = () => {
    if (!dragEl) return;
    dragEl.classList.remove("is-dragging");
    dragEl = null;
    started = false;
  };
  document.addEventListener("pointerup", end);
  document.addEventListener("pointercancel", end);

